function field([name,label,type],row={}){const val=esc(row[name]||'');if(type==='roles'){const selected=String(row[name]||'').split(',');return `<div class="field wide"><label>${label}</label><div class="actions">${['ADMIN','CONTROL','PROPIETARIO'].map(role=>`<label class="btn secondary" style="cursor:pointer"><input class="role-check" type="checkbox" value="${role}" ${selected.includes(role)?'checked':''}> ${role}</label>`).join('')}</div><span class="muted" style="font-size:.8rem">Selecciona uno o dos perfiles.</span></div>`}if(type==='owner'){const options=(state.cache.formOptions?.owners||[]).map(u=>`<option value="${esc(u.Email)}" ${u.Email===row[name]?'selected':''}>${esc(ownerLabel(u))}</option>`).join('');return `<div class="field"><label>${label}</label><select name="${name}" required><option value="">Selecciona propietario</option>${options}</select></div>`}if(type==='housing'){const options=(state.cache.formOptions?.housing||[]).map(h=>`<option value="${esc(h.ID_Vivienda)}" ${h.ID_Vivienda===row[name]?'selected':''}>${esc(housingLabel(h))}</option>`).join('');return `<div class="field wide"><label>${label}</label><select name="${name}" required><option value="">Selecciona vivienda</option>${options}</select></div>`}if(type.startsWith('select:'))return `<div class="field"><label>${label}</label><select name="${name}">${type.slice(7).split('|').map(o=>`<option ${o===row[name]?'selected':''}>${o}</option>`).join('')}</select></div>`;if(type==='textarea')return `<div class="field"><label>${label}</label><textarea name="${name}">${val}</textarea></div>`;return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${val}"></div>`}
function editor(kind,row){if(kind==='vehicles')return vehicleEditor(row);const c=configs[kind];$('#editor').innerHTML=`<form class="card form" id="edit-form"><h2 class="wide">${row?'Editar':'Nuevo'} ${c.title.toLowerCase()}</h2>${c.fields.map(f=>field(f,row||{})).join('')}<div class="wide actions"><button>Guardar</button><button type="button" class="secondary" id="cancel">Cancelar</button></div></form>`;$('#cancel').onclick=()=>$('#editor').innerHTML='';$('#edit-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));if(kind==='users'){const roles=[...e.target.querySelectorAll('.role-check:checked')].map(x=>x.value);if(!roles.length||roles.length>2){toast('Selecciona uno o dos perfiles.',true);busy(b,false);return}data.Rol=roles.join(',')}if(row)data[c.id]=row[c.id];try{await call(c.save,data);toast('Datos guardados.');manager(kind)}catch(x){toast(x.message,true);busy(b,false)}};$('#editor').scrollIntoView({behavior:'smooth'})}
function availableSlotsClient(housingId,excludeId=''){const used=(state.cache.vehicles||[]).filter(v=>v.ID_Vivienda===housingId&&v.Estado==='Activo'&&v.ID_Vehiculo!==excludeId).map(v=>String(v.Slot));return ['1','2'].filter(x=>!used.includes(x))}
function vehicleEditor(row,contextHousing=null){
  const hOpts=state.cache.formOptions?.housing||[],base=row||{},selectedHousing=base.ID_Vivienda||contextHousing?.ID_Vivienda||'',housingOptions=hOpts.map(h=>`<option value="${esc(h.ID_Vivienda)}" ${h.ID_Vivienda===selectedHousing?'selected':''}>${esc(housingLabel(h))}</option>`).join('');
  $('#editor').innerHTML=`<form class="card form" id="edit-form"><h2 class="wide">${row?'Editar':'Nuevo'} vehículo</h2><div class="field wide"><label>Vivienda</label><select name="ID_Vivienda" id="veh-housing" required><option value="">Selecciona vivienda</option>${housingOptions}</select></div><div class="field"><label>Estado</label><select name="Estado" id="veh-state">${['Activo','Suspendido','Baja'].map(x=>`<option ${x===(base.Estado||'Activo')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Slot</label><select name="Slot" id="veh-slot"></select><span class="muted" id="slot-help" style="font-size:.78rem"></span></div>${[['MatriculaHabitual','Matrícula habitual','text'],['MatriculaTemporal','Matrícula temporal','text'],['TemporalDesde','Temporal desde','date'],['TemporalHasta','Temporal hasta','date'],['Marca','Marca','text'],['Modelo','Modelo','text'],['Tipo','Tipo','select:Particular|Empresa|Alquiler|Otro'],['Observaciones','Observaciones','textarea']].map(f=>field(f,base)).join('')}<div class="field"><label>Estado QR</label><select name="QR_Estado" id="veh-qr"><option ${base.QR_Estado!=='Revocado'?'selected':''}>Activo</option><option ${base.QR_Estado==='Revocado'?'selected':''}>Revocado</option></select></div><div class="wide actions"><button>Guardar</button><button type="button" class="secondary" id="cancel">Cancelar</button></div></form>`;
  const refresh=()=>{const hid=$('#veh-housing').value,stateVal=$('#veh-state').value,slot=$('#veh-slot'),qr=$('#veh-qr'),free=availableSlotsClient(hid,row?.ID_Vehiculo||''),tempFields=['MatriculaTemporal','TemporalDesde','TemporalHasta'].map(n=>document.querySelector(`#edit-form [name="${n}"]`)).filter(Boolean);const tempBlocked=stateVal!=='Activo';tempFields.forEach(x=>x.readOnly=tempBlocked);let tempHelp=$('#temp-help');if(!tempHelp){tempHelp=document.createElement('div');tempHelp.id='temp-help';tempHelp.className='message wide';document.querySelector('#edit-form .actions').before(tempHelp)}tempHelp.classList.toggle('hide',!tempBlocked);tempHelp.textContent='La matrícula temporal se conserva como histórico, pero no tiene validez y no puede modificarse mientras el vehículo no esté activo.';if(stateVal!=='Activo'){slot.innerHTML='<option value="">Liberado</option>';slot.disabled=true;qr.value='Revocado';qr.disabled=true;$('#slot-help').textContent='Suspendido/Baja libera el slot y revoca el QR.';return}slot.disabled=false;const current=row?.Estado==='Activo'&&row?.ID_Vivienda===hid?String(row.Slot||''):'';slot.innerHTML=free.map(x=>`<option value="${x}" ${x===current?'selected':''}>Slot ${x}</option>`).join('')||'<option value="">Sin slots disponibles</option>';qr.disabled=!!(row&&row.Estado!=='Activo');if(row&&row.Estado!=='Activo'){qr.value='Revocado';$('#slot-help').textContent=free.length?`Disponible: ${free.map(x=>'Slot '+x).join(', ')}. Al reactivar, el QR seguirá revocado hasta renovarlo.`:'No hay slots disponibles para reactivar.'}else $('#slot-help').textContent=free.length?`Slots disponibles: ${free.map(x=>'Slot '+x).join(', ')}`:'No hay slots disponibles.'};
  $('#veh-housing').onchange=refresh;$('#veh-state').onchange=refresh;refresh();$('#cancel').onclick=()=>contextHousing?housingVehicles(contextHousing):$('#editor').innerHTML='';$('#edit-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));if($('#veh-qr').disabled)data.QR_Estado=$('#veh-qr').value;if(row)data.ID_Vehiculo=row.ID_Vehiculo;try{await call('saveVehicle',data);toast('Datos guardados.');contextHousing?housingVehicles(contextHousing):manager('vehicles')}catch(x){toast(x.message,true);busy(b,false)}};$('#editor').scrollIntoView({behavior:'smooth'})
}

async function showQr(v,backFn=null){const valid=v.Estado==='Activo'&&v.QR_Estado==='Activo';$('#main').innerHTML=`<div class="head"><h1>QR del vehículo</h1><button class="secondary" id="back-list">Volver</button></div><div class="grid"><div class="card result ${valid?'':'bad'}"><span class="status ${valid?'':'bad'}">${esc(v.Estado)} · QR ${esc(v.QR_Estado)}</span><div class="plate" style="font-size:2.5rem">${esc(v.MatriculaHabitual)}</div><p>${esc(v.Marca)} ${esc(v.Modelo)}</p></div><div class="card" style="text-align:center"><h2>Código QR</h2>${valid?`<div id="qr"><div class="spinner"></div></div><p class="muted">Contiene únicamente un token aleatorio.</p><button id="print">Imprimir</button>`:`<div class="message bad">Este vehículo no tiene un QR válido. Debe estar Activo y con QR Activo.</div>`}</div></div>`;$('#back-list').onclick=backFn||vehicles;if(!valid)return;$('#print').onclick=()=>window.print();try{await ensureQr();$('#qr').innerHTML='';const size=qrSize();new QRCode($('#qr'),{text:qrTarget(v.QR_Token),width:size,height:size,correctLevel:QRCode.CorrectLevel.L})}catch(e){$('#qr').innerHTML=`<div class="message bad">${esc(e.message)}</div>`}}

async function control(token=''){
  if(token){
    $('#main').innerHTML=`<section class="hero"><h1>Control de acceso</h1><p>Comprobando el código escaneado.</p></section><div id="control-body"><section class="card loading-state"><div class="spinner"></div><h2>Comprobando QR…</h2><p class="muted">Validando vehículo y autorización de acceso.</p></section></div>`;
    await lookupQr(token);
    return;
  }
  const returnUrl=WEB_APP_URL||location.href.split('?')[0];
  const scannerUrl=EXTERNAL_SCANNER_URL+'?return='+encodeURIComponent(returnUrl);
  $('#main').innerHTML=`<section class="hero"><h1>Control de acceso</h1><p>Escanea, comprueba y registra en pocos segundos.</p></section><div id="control-body" class="grid"><a class="btn big" id="scan" href="${esc(scannerUrl)}" target="_top">▣ ESCANEAR QR</a><button class="big" id="plate">⌕ BUSCAR MATRÍCULA</button><button class="big secondary" id="open-inc">! INCIDENCIAS ABIERTAS</button><button class="big secondary" id="new-inc">＋ REGISTRAR INCIDENCIA</button></div>`;
  $('#plate').onclick=plateSearch;$('#open-inc').onclick=incidents;$('#new-inc').onclick=()=>incidentForm();
}
async function startScanner(){
  $('#control-body').innerHTML=`<div class="card wide"><div class="head"><h2>Escanear QR</h2><button class="secondary" id="cback">Volver</button></div><div id="qr-reader" style="width:100%;min-height:260px"></div><div id="qr-file-reader" class="hide"></div><div id="camera-error"><div class="spinner"></div></div><div class="actions" style="margin-top:1rem"><button class="secondary" id="retry-camera" type="button">Reintentar cámara</button><label class="btn secondary" for="qr-file">Leer desde una foto</label><input id="qr-file" type="file" accept="image/*" capture="environment" class="hide"><button class="secondary" id="manual-code" type="button">Introducir código</button></div></div>`;
  $('#cback').onclick=()=>control();$('#retry-camera').onclick=startScanner;$('#manual-code').onclick=manualQr;
  $('#qr-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;stopScanner();$('#camera-error').innerHTML='<div class="spinner"></div>';try{await ensureScanner();const fileReader=new Html5Qrcode('qr-file-reader');const text=await fileReader.scanFile(file,true);lookupQr(text)}catch(x){$('#camera-error').innerHTML=`<div class="message bad">${esc(x.message.includes('componente')?x.message:'No se pudo leer el QR de la imagen. Acércate más, evita reflejos y vuelve a intentarlo.')}</div>`}};
  try{
    await ensureScanner();state.scanner=new Html5Qrcode('qr-reader');
    await state.scanner.start({facingMode:'environment'},{fps:12,qrbox:(w,h)=>{const size=Math.floor(Math.min(w,h)*.72);return {width:size,height:size}},aspectRatio:1.333},text=>{const scanner=state.scanner;state.scanner=null;if(scanner)scanner.stop().catch(()=>{});navigator.vibrate?.(120);lookupQr(text)},()=>{});
    $('#camera-error').innerHTML='<div class="message">Apunta al QR y mantenlo dentro del recuadro.</div>';
  }catch(e){state.scanner=null;$('#camera-error').innerHTML=`<div class="message bad">No se pudo iniciar la cámara en directo. Revisa el permiso del navegador o usa “Leer desde una foto”.</div>`}
}
function manualQr(){const value=prompt('Pega la URL del QR o escribe su token:');if(value&&value.trim())lookupQr(value.trim())}
async function lookupQr(value){try{const r=await call('scanQr',{token:value});resultCard(r)}catch(e){err(e)}}
function plateSearch(){$('#control-body').innerHTML=`<div class="card wide"><div class="head"><h2>Buscar matrícula</h2><button class="secondary" id="cback">Volver</button></div><form id="search-form" class="actions"><input class="search" name="plate" placeholder="1234 ABC" required><button>Buscar</button></form></div>`;$('#cback').onclick=()=>control();$('#search-form').onsubmit=async e=>{e.preventDefault();try{resultCard(await call('searchPlate',{plate:new FormData(e.target).get('plate')}))}catch(x){err(x)}}}
function resultCard(r){state.scanResult=r;const v=r.vehicle||{},h=r.housing||{},o=r.owner||{},good=r.status==='AUTORIZADO',shown=r.query||r.currentPlate||'';$('#control-body').innerHTML=`<article class="card result wide ${good?'':'bad'}"><h2>${esc(r.status)}</h2>${shown?`<div class="plate">${esc(shown)}</div>`:''}${v.ID_Vehiculo?`<div class="details"><div><small>Vivienda</small>${esc(housingShort(h))}</div><div><small>Propietario</small>${esc(o.Nombre||h.Responsable||'Sin responsable')}</div>${o.Telefono?`<div><small>Teléfono</small>${esc(o.Telefono)}</div>`:''}<div><small>Slot</small>${esc(v.Slot)}</div><div><small>Tipo</small>${esc(v.Tipo)}</div><div><small>Matrícula habitual</small>${esc(v.MatriculaHabitual||'—')}</div>${v.MatriculaTemporal?`<div><small>Matrícula temporal</small>${esc(v.MatriculaTemporal)}${v.Estado!=='Activo'?`<span class="subtle">No válida mientras el vehículo no esté activo</span>`:r.isTemporary?`<span class="subtle temp-active">Vigente hasta ${esc(dateEs(v.TemporalHasta))}</span>`:`<span class="subtle">No vigente</span>`}</div>`:''}<div><small>Estado vehículo</small>${esc(v.Estado||'—')}</div><div><small>Estado QR</small>${esc(v.QR_Estado||'—')}</div></div>`:''}<div class="actions" style="justify-content:center;margin-top:1rem"><button id="incident-result">Registrar incidencia</button><button class="secondary" id="again">Otra consulta</button></div></article>`;$('#again').onclick=()=>control();$('#incident-result').onclick=()=>incidentForm(Object.assign({},r,{query:shown}))}

function requestTypeLabel(v){return v==='REACTIVACION_VEHICULO'?'Reactivación de vehículo':v==='RENOVACION_QR'?'Renovación de QR':v}
const PAGE_SIZE=20;
function shortDateTime(v){if(!v)return '—';const x=String(v);const d=x.slice(0,10),t=x.length>=16?x.slice(11,16):'';return `${dateEs(d)}${t?' '+t:''}`}
function recordHousingLabel(r,h=null){if(h)return housingShort(h);if(r&&r.Bloque)return `Bloque ${r.Bloque}, ${r.Planta||''} ${r.Apartamento||''}`.replace(/\s+/g,' ').trim();return r?.ID_Vivienda||'—'}
function requestSummaryForVehicle(id){const rows=(state.cache.adminRequests||[]).filter(r=>r.ID_Vehiculo===id&&r.Estado==='Pendiente');if(!rows.length)return '<span class="request-chip none">—</span>';const labels=[...new Set(rows.map(r=>r.Tipo==='REACTIVACION_VEHICULO'?'Reactivación':'Renovación QR'))],first=rows[0];return `<button type="button" class="request-chip request-chip-btn" data-request-id="${esc(first.ID_Solicitud)}" title="Abrir solicitud">● ${rows.length} · ${esc(labels.join(' + '))}</button>`}
function incidentSummaryForVehicle(id){const rows=(state.cache.adminIncidents||[]).filter(r=>r.ID_Vehiculo===id&&r.Estado!=='Cerrada');if(!rows.length)return '<span class="request-chip none">—</span>';const first=rows[0];return `<button type="button" class="request-chip request-chip-btn incident-chip-btn" data-incident-id="${esc(first.ID_Incidencia)}" title="Abrir incidencia">● ${rows.length} pendiente${rows.length===1?'':'s'}</button>`}
function invalidateClientParkingData(){delete state.cache.adminRequests;delete state.cache.adminIncidents;delete state.cache.vehicles;delete state.cache.ownerHousing;delete state.cache.ownerVehicles;delete state.cache.ownerRequests;delete state.cache.bootstrap}
function bindRequestLinks(){document.querySelectorAll('.request-chip-btn').forEach(b=>b.onclick=()=>{state.cache.requestFocus=b.dataset.requestId||'';go('requests')})}
