function pagerHtml(id,page,total){const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));return `<div class="pager"><span class="muted">Página ${page} de ${pages} · ${total} registros</span><div class="actions"><button class="secondary" id="${id}-prev" ${page<=1?'disabled':''}>← Anterior</button><button class="secondary" id="${id}-next" ${page>=pages?'disabled':''}>Siguiente →</button></div></div>`}

async function requests(openId=''){
  try{
    const focusId=openId||state.cache.requestFocus||'';delete state.cache.requestFocus;
    const rows=await call('listRequests');let page=1;
    $('#main').innerHTML=`<div class="head"><h1>Solicitudes</h1></div><div id="request-detail"></div><div class="filterbar"><div class="field filter-search"><label>Buscar</label><input id="req-search" class="search" placeholder="Matrícula, vivienda o solicitante..."></div><div class="field"><label>Estado</label><select id="req-state"><option value="Pendiente" selected>Pendientes</option><option value="">Todas</option><option>Aprobada</option><option>Rechazada</option></select></div><div class="field"><label>Tipo</label><select id="req-type"><option value="">Todos</option><option value="REACTIVACION_VEHICULO">Reactivación</option><option value="RENOVACION_QR">Renovación QR</option></select></div><span class="count" id="req-count"></span></div><div class="tablebox compact-table"><table class="table"><thead><tr><th>Fecha</th><th>Matrícula</th><th>Vivienda</th><th>Solicitante</th><th>Tipo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="req-body"></tbody></table><div id="req-empty" class="empty hide">No hay solicitudes.</div></div><div id="req-pager"></div>`;
    const filtered=()=>{const q=$('#req-search').value.trim().toLowerCase(),st=$('#req-state').value,tp=$('#req-type').value;return rows.filter(r=>(!st||r.Estado===st)&&(!tp||r.Tipo===tp)&&Object.values(r).join(' ').toLowerCase().includes(q))};
    const detail=r=>{const host=$('#request-detail');host.innerHTML=`<section class="card detail-panel"><div class="head"><div><h3>${esc(requestTypeLabel(r.Tipo))} · ${esc(r.MatriculaHabitual||'SIN MATRÍCULA')}</h3><span class="status ${r.Estado==='Pendiente'?'bad':''}">${esc(r.Estado)}</span></div><button class="secondary" id="req-detail-close">Cerrar</button></div><div class="details"><div><small>Vivienda</small>${esc(`Bloque ${r.Bloque}, ${r.Planta} ${r.Apartamento}`)}</div><div><small>Solicitante</small>${esc(r.NombreSolicitante||r.Usuario)}</div><div><small>Estado vehículo</small>${esc(r.EstadoVehiculo||'—')}</div><div><small>Estado QR</small>${esc(r.EstadoQR||'—')}</div><div><small>Fecha</small>${esc(shortDateTime(r.FechaHora))}</div></div>${r.Motivo?`<p><b>Motivo:</b> ${esc(r.Motivo)}</p>`:''}${r.Estado!=='Pendiente'?`<div class="message"><b>Resolución:</b> ${esc(r.Estado)}<br><b>Comentario:</b> ${esc(r.ObservacionesResolucion||'—')}<br><span class="subtle">${esc(r.Estado==='Aprobada'?'Aprobada':'Rechazada')} por ${esc(r.NombreResolucion||r.UsuarioResolucion||'—')} · ${esc(shortDateTime(r.FechaResolucion))}</span></div>`:''}${r.Estado==='Pendiente'?`<div class="actions">${r.Tipo==='REACTIVACION_VEHICULO'?`<select id="req-detail-slot">${(r.SlotsDisponibles||[]).map(x=>`<option value="${x}">Slot ${x}</option>`).join('')||'<option value="">Sin slots libres</option>'}</select>`:''}<button id="req-detail-approve" ${r.Tipo==='REACTIVACION_VEHICULO'&&!(r.SlotsDisponibles||[]).length?'disabled':''}>Aprobar</button><button class="secondary" id="req-detail-reject">Rechazar</button></div>`:''}</section>`;$('#req-detail-close').onclick=()=>host.innerHTML='';if(r.Estado==='Pendiente'){const approve=$('#req-detail-approve'),reject=$('#req-detail-reject');if(approve)approve.onclick=async()=>{const slot=$('#req-detail-slot')?.value||'',obs=prompt('Observaciones de resolución (opcional):','')||'';try{await call('resolveRequest',{id:r.ID_Solicitud,decision:'Aprobada',slot,observaciones:obs});invalidateClientParkingData();toast('Solicitud aprobada.');requests(r.ID_Solicitud)}catch(e){err(e)}};if(reject)reject.onclick=async()=>{const obs=prompt('Motivo del rechazo (opcional):','')||'';try{await call('resolveRequest',{id:r.ID_Solicitud,decision:'Rechazada',observaciones:obs});invalidateClientParkingData();toast('Solicitud rechazada.');requests(r.ID_Solicitud)}catch(e){err(e)}}}host.scrollIntoView({behavior:'smooth',block:'start'})};
    const render=()=>{const list=filtered(),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.min(page,pages);const slice=list.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);$('#req-count').textContent=`Mostrando ${slice.length?((page-1)*PAGE_SIZE+1):0}–${Math.min(page*PAGE_SIZE,list.length)} de ${list.length}`;$('#req-body').innerHTML=slice.map(r=>`<tr><td>${esc(shortDateTime(r.FechaHora))}</td><td><b>${esc(r.MatriculaHabitual||'—')}</b></td><td>${esc(`Bloque ${r.Bloque}, ${r.Planta} ${r.Apartamento}`)}</td><td>${esc(r.NombreSolicitante||r.Usuario)}</td><td>${esc(requestTypeLabel(r.Tipo))}</td><td><span class="status ${r.Estado==='Pendiente'?'bad':''}">${esc(r.Estado)}</span></td><td><button class="secondary req-view" data-id="${esc(r.ID_Solicitud)}">Ver</button></td></tr>`).join('');$('#req-empty').classList.toggle('hide',!!list.length);$('#req-pager').innerHTML=pagerHtml('req',page,list.length);document.querySelectorAll('.req-view').forEach(b=>b.onclick=()=>detail(rows.find(r=>r.ID_Solicitud===b.dataset.id)));$('#req-prev').onclick=()=>{page--;render()};$('#req-next').onclick=()=>{page++;render()}};
    const reset=()=>{page=1;render()};$('#req-search').oninput=reset;$('#req-state').onchange=reset;$('#req-type').onchange=reset;render();if(focusId){const target=rows.find(r=>r.ID_Solicitud===focusId);if(target)detail(target)}
  }catch(e){err(e)}
}

async function incidents(openId=''){
  try{
    const focusId=openId||state.cache.incidentFocus||'';delete state.cache.incidentFocus;
    const rows=await call('listIncidents');state.cache.incidents=rows;let page=1;const types=['Matrícula no registrada','QR revocado','Vehículo suspendido','Vehículo de baja','QR no corresponde con matrícula','Vehículo sin QR','Uso indebido','Otro'];
    $('#main').innerHTML=`<div class="head"><h1>Incidencias</h1><button id="add-inc">＋ Registrar</button></div><div id="incident-editor"></div><div id="incident-detail"></div><div class="filterbar"><div class="field filter-search"><label>Buscar</label><input id="incident-search" class="search" placeholder="Matrícula, tipo o descripción..."></div><div class="field"><label>Estado</label><select id="incident-state"><option value="Abierta" selected>Pendientes</option><option value="">Todas</option><option>Cerrada</option></select></div><div class="field"><label>Tipo</label><select id="incident-type"><option value="">Todos</option>${types.map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><span class="count" id="incident-count"></span></div><div class="tablebox compact-table"><table class="table"><thead><tr><th>Fecha</th><th>Matrícula</th><th>Vivienda</th><th>Tipo</th><th>Estado</th><th>Origen</th><th>Acciones</th></tr></thead><tbody id="incident-body"></tbody></table><div id="incident-empty" class="empty hide">No hay incidencias.</div></div><div id="incident-pager"></div>`;
    const housingMap=Object.fromEntries((state.cache.formOptions?.housing||[]).map(h=>[h.ID_Vivienda,h]));
    const filtered=()=>{const q=$('#incident-search').value.trim().toLowerCase(),type=$('#incident-type').value,status=$('#incident-state').value;return rows.filter(r=>(!type||r.Tipo===type)&&(!status||r.Estado===status)&&Object.values(r).join(' ').toLowerCase().includes(q))};
    const detail=r=>{const h=housingMap[r.ID_Vivienda],host=$('#incident-detail'),linked=!!r.ID_Vehiculo,active=r.EstadoVehiculo==='Activo';host.innerHTML=`<section class="card detail-panel"><div class="head"><div><h3>${esc(r.Tipo)} · ${esc(r.MatriculaObservada||'SIN MATRÍCULA')}</h3><span class="status ${r.Estado==='Cerrada'?'':'bad'}">${esc(r.Estado||'Abierta')}</span></div><button class="secondary" id="inc-detail-close">Cerrar detalle</button></div><div class="details"><div><small>Fecha</small>${esc(shortDateTime(r.FechaHora))}</div><div><small>Vivienda</small>${esc(recordHousingLabel(r,h))}</div><div><small>Usuario</small>${esc(r.NombreUsuario||r.Usuario||'—')}</div><div><small>Origen</small>${esc(r.OrigenControl||'Manual')}</div>${r.EstadoOrigen?`<div><small>Estado detectado</small>${esc(r.EstadoOrigen)}</div>`:''}${linked?`<div><small>Vehículo vinculado</small>${esc(r.MatriculaHabitualVehiculo||r.MatriculaAutorizada||'Sí')}</div><div><small>Estado vehículo</small>${esc(r.EstadoVehiculo||'—')}</div><div><small>Estado QR</small>${esc(r.EstadoQR||'—')}</div>`:''}</div><p>${esc(r.Descripcion||'')}</p>${r.Estado==='Cerrada'?`<div class="message"><b>Acción de cierre:</b> ${esc(r.AccionCierre||'Sin actuación')}<br><b>Comentario:</b> ${esc(r.ComentarioCierre||'—')}<br><span class="subtle">Cerrada por ${esc(r.NombreUsuarioCierre||r.UsuarioCierre||'—')} · ${esc(shortDateTime(r.FechaCierre))}</span></div>`:''}<div class="actions">${r.Foto?`<a class="btn secondary" href="${esc(r.Foto)}" target="_blank">Ver foto</a>`:''}${hasUiRole('ADMIN')&&r.Estado==='Abierta'?`<button id="inc-detail-close-case">Resolver / cerrar</button>`:''}</div><div id="incident-close-editor"></div></section>`;$('#inc-detail-close').onclick=()=>host.innerHTML='';const close=$('#inc-detail-close-case');if(close)close.onclick=()=>{const actions=['Sin actuación','Aviso al propietario','Datos corregidos','Otra'].concat(linked&&active?['Revocar QR','Suspender vehículo','Dar de baja']:[]);$('#incident-close-editor').innerHTML=`<form class="form" id="incident-close-form" style="margin-top:1rem"><div class="field"><label>Acción realizada</label><select name="AccionCierre">${actions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field wide"><label>Comentario de cierre</label><textarea name="ComentarioCierre" placeholder="Qué se hizo, contacto con propietario, observaciones..."></textarea></div>${linked&&!active?`<div class="message wide">El vehículo está ${esc(r.EstadoVehiculo||'no activo')}. Las acciones que modifican acceso solo están disponibles para vehículos activos.</div>`:''}<div class="wide actions"><button>Cerrar incidencia</button><button type="button" class="secondary" id="cancel-close-inc">Cancelar</button></div></form>`;$('#cancel-close-inc').onclick=()=>$('#incident-close-editor').innerHTML='';$('#incident-close-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),action=data.AccionCierre;if(action==='Otra'&&!String(data.ComentarioCierre||'').trim()){toast('Añade un comentario para la acción Otra.',true);return}const destructive=['Revocar QR','Suspender vehículo','Dar de baja'].includes(action);if(destructive&&!confirm(`${action} sobre ${r.MatriculaHabitualVehiculo||r.MatriculaObservada}. Esta acción modificará el vehículo y cerrará la incidencia. ¿Continuar?`))return;const b=e.submitter;busy(b);try{await call('closeIncident',Object.assign({id:r.ID_Incidencia},data));toast('Incidencia cerrada.');invalidateClientParkingData();incidents()}catch(x){toast(x.message,true);busy(b,false)}}};host.scrollIntoView({behavior:'smooth',block:'start'})};
    const render=()=>{const list=filtered(),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.min(page,pages);const slice=list.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);$('#incident-count').textContent=`Mostrando ${slice.length?((page-1)*PAGE_SIZE+1):0}–${Math.min(page*PAGE_SIZE,list.length)} de ${list.length}`;$('#incident-body').innerHTML=slice.map(r=>{const h=housingMap[r.ID_Vivienda];return `<tr><td>${esc(shortDateTime(r.FechaHora))}</td><td><b>${esc(r.MatriculaObservada||'—')}</b></td><td>${esc(recordHousingLabel(r,h))}</td><td>${esc(r.Tipo)}</td><td><span class="status ${r.Estado==='Cerrada'?'':'bad'}">${esc(r.Estado||'Abierta')}</span></td><td>${esc(r.OrigenControl||'Manual')}</td><td><button class="secondary inc-view" data-id="${esc(r.ID_Incidencia)}">Ver</button></td></tr>`}).join('');$('#incident-empty').classList.toggle('hide',!!list.length);$('#incident-pager').innerHTML=pagerHtml('incident',page,list.length);document.querySelectorAll('.inc-view').forEach(b=>b.onclick=()=>detail(rows.find(r=>r.ID_Incidencia===b.dataset.id)));$('#incident-prev').onclick=()=>{page--;render()};$('#incident-next').onclick=()=>{page++;render()}};
    const reset=()=>{page=1;render()};$('#add-inc').onclick=()=>incidentForm(null);$('#incident-search').oninput=reset;$('#incident-type').onchange=reset;$('#incident-state').onchange=reset;render();if(focusId){const target=rows.find(r=>r.ID_Incidencia===focusId);if(target)detail(target)}
  }catch(e){err(e)}
}

function incidentTypeFromStatus(status){const map={'MATRICULA NO REGISTRADA':'Matrícula no registrada','QR REVOCADO':'QR revocado','QR NO ENCONTRADO':'Vehículo sin QR','VEHICULO SUSPENDIDO':'Vehículo suspendido','VEHICULO DE BAJA':'Vehículo de baja'};return map[status]||'Otro'}
function incidentForm(prefill=state.scanResult){const p=prefill||{},v=p.vehicle||{},plate=p.query||p.currentPlate||'',status=p.status||'',origin=p.source||'';const host=state.view==='control'?$('#control-body'):$('#incident-editor');const selected=incidentTypeFromStatus(status),types=['Matrícula no registrada','QR revocado','Vehículo suspendido','Vehículo de baja','QR no corresponde con matrícula','Vehículo sin QR','Uso indebido','Otro'];host.innerHTML=`<form class="card form" id="incident-form"><h2 class="wide">Registrar incidencia</h2><div class="field"><label>Matrícula observada</label><input name="MatriculaObservada" value="${esc(plate)}"></div><div class="field"><label>Estado detectado</label><input value="${esc(status||'Registro manual')}" disabled></div><div class="field"><label>Tipo</label><select name="Tipo">${types.map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}</select></div><div class="field wide"><label>Descripción</label><textarea name="Descripcion" required></textarea></div><div class="field"><label>Foto</label><input id="photo" type="file" accept="image/*" capture="environment"></div><input type="hidden" name="Foto"><input type="hidden" name="EstadoOrigen" value="${esc(status)}"><input type="hidden" name="OrigenControl" value="${esc(origin)}"><div class="wide actions"><button>Registrar</button><button type="button" class="secondary" id="cancel-inc">Cancelar</button></div></form>`;$('#cancel-inc').onclick=()=>state.view==='control'?control():incidents();$('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024){toast('La foto original no puede superar 12 MB.',true);return}toast('Optimizando fotografía…');try{const dataUrl=await optimizedImageData(file);const out=await call('uploadPhoto',{dataUrl});$('#incident-form [name=Foto]').value=out.url;toast('Foto subida.')}catch(x){err(x)}};$('#incident-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));Object.assign(data,{MatriculaAutorizada:p.currentPlate||'',ID_Vivienda:v.ID_Vivienda||'',ID_Vehiculo:v.ID_Vehiculo||''});try{const out=await call('saveIncident',data);toast('Incidencia '+out.ID_Incidencia+' registrada.');state.view==='control'?control():incidents()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
function fileData(file){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)})}
async function optimizedImageData(file){try{const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);if(bitmap.close)bitmap.close();return canvas.toDataURL('image/jpeg',.82)}catch(e){return fileData(file)}}

function auditValue(value,name){if(!value)return '—';return name?`<b>${esc(name)}</b><span class="subtle">${esc(value)}</span>`:esc(value)}
async function audit(){try{const rows=(await call('listAudit')).reverse();$('#main').innerHTML=`<div class="head"><h1>Auditoría</h1></div><div class="filterbar"><div class="field filter-search"><label>Buscar</label><input id="audit-search" class="search" placeholder="Nombre, email, acción, entidad o valor..."></div><div class="field"><label>Entidad</label><select id="audit-entity"><option value="">Todas</option>${[...new Set(rows.map(r=>r.Entidad).filter(Boolean))].map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><span class="count" id="audit-count"></span></div><div class="tablebox"><table class="table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Campo</th><th>Antes</th><th>Después</th></tr></thead><tbody id="audit-body"></tbody></table></div>`;const render=()=>{const q=$('#audit-search').value.trim().toLowerCase(),entity=$('#audit-entity').value,filtered=rows.filter(r=>(!entity||r.Entidad===entity)&&Object.values(r).join(' ').toLowerCase().includes(q));$('#audit-count').textContent=`Mostrando ${filtered.length} de ${rows.length}`;$('#audit-body').innerHTML=filtered.map(r=>`<tr><td>${esc(r.FechaHora)}</td><td><b>${esc(r.UsuarioNombre||r.Usuario)}</b>${r.UsuarioNombre&&r.Usuario?`<span class="subtle">${esc(r.Usuario)}</span>`:''}</td><td>${esc(r.Accion)}</td><td>${esc(r.Entidad)} · ${esc(r.ID_Entidad)}</td><td>${esc(r.Campo)}</td><td>${auditValue(r.ValorAnterior,r.ValorAnteriorNombre)}</td><td>${auditValue(r.ValorNuevo,r.ValorNuevoNombre)}</td></tr>`).join('')};$('#audit-search').oninput=render;$('#audit-entity').onchange=render;render()}catch(e){err(e)}}

async function ownerData(force=false){
  if(!force&&state.cache.ownerHousing&&state.cache.ownerVehicles&&state.cache.ownerRequests)return {hs:state.cache.ownerHousing,vs:state.cache.ownerVehicles,reqs:state.cache.ownerRequests};
  const bundle=await call('ownerBundle');
  const hs=bundle.housing||[],vs=bundle.vehicles||[],reqs=bundle.requests||[];
  state.cache.ownerHousing=hs;state.cache.ownerVehicles=vs;state.cache.ownerRequests=reqs;
  return {hs,vs,reqs}
}
function ownerHousingMap(hs){const out={};(hs||[]).forEach(h=>out[h.ID_Vivienda]=h);return out}
function ownerHousingCard(h,vs){const own=vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda),active=own.filter(v=>v.Estado==='Activo').length,canAdd=h.Estado==='Activa'&&active<2;return `<article class="card"><div class="head"><h2>${esc(housingShort(h))}</h2><span class="status ${h.Estado==='Activa'?'':'bad'}">${esc(h.Estado)}</span></div><div class="details"><div><small>Vehículos activos</small>${active}/2</div><div><small>Vehículos registrados</small>${own.length}</div><div><small>Slots libres</small>${Math.max(0,2-active)}</div></div><div class="actions" style="margin-top:1rem"><button class="secondary owner-housing-vehicles" data-id="${esc(h.ID_Vivienda)}">Ver vehículos</button>${canAdd?`<button class="owner-housing-add" data-id="${esc(h.ID_Vivienda)}">＋ Añadir vehículo</button>`:''}</div></article>`}
async function ownerHousing(){try{const {hs,vs}=await ownerData();$('#main').innerHTML=`<section class="hero"><h1>Mis viviendas</h1><p>${hs.length===1?'1 vivienda asociada':`${hs.length} viviendas asociadas`} a tu usuario.</p></section><div class="grid">${hs.map(h=>ownerHousingCard(h,vs)).join('')||'<div class="card empty">No tienes viviendas asignadas.</div>'}</div>`;document.querySelectorAll('.owner-housing-vehicles').forEach(b=>b.onclick=()=>{state.cache.ownerHousingFilter=b.dataset.id;go('ownerVehicles')});document.querySelectorAll('.owner-housing-add').forEach(b=>b.onclick=()=>ownerAddVehicle(b.dataset.id))}catch(e){err(e)}}
async function ownerVehicles(){try{const {hs,vs,reqs}=await ownerData(),map=ownerHousingMap(hs),filter=state.cache.ownerHousingFilter||'',shown=filter?hs.filter(h=>h.ID_Vivienda===filter):hs;state.cache.ownerRequests=reqs;$('#main').innerHTML=`<div class="head"><h1>Mis vehículos</h1>${filter?'<button class="secondary" id="owner-clear-house">Ver todas las viviendas</button>':''}</div><div id="owner-editor"></div>${shown.map(h=>{const rows=vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda),active=rows.filter(v=>v.Estado==='Activo').length,canAdd=h.Estado==='Activa'&&active<2;return `<section class="card" style="margin-bottom:1rem"><div class="head"><div><h2>${esc(housingShort(h))}</h2><span class="muted">Slots ocupados ${active}/2</span></div>${canAdd?`<button class="owner-add" data-id="${esc(h.ID_Vivienda)}">＋ Añadir vehículo</button>`:''}</div><div class="grid">${rows.map(v=>ownerVehicle(v,vs.indexOf(v),h)).join('')||'<div class="empty">No hay vehículos registrados.</div>'}</div></section>`}).join('')||'<div class="card empty">No tienes viviendas asignadas.</div>'}`;$('#owner-clear-house')&&($('#owner-clear-house').onclick=()=>{delete state.cache.ownerHousingFilter;ownerVehicles()});document.querySelectorAll('.owner-add').forEach(b=>b.onclick=()=>ownerAddVehicle(b.dataset.id));document.querySelectorAll('.owner-edit').forEach(b=>b.onclick=()=>ownerEditor(vs[b.dataset.i]));document.querySelectorAll('.owner-qr').forEach(b=>b.onclick=()=>ownerQr(vs[b.dataset.i]));document.querySelectorAll('.owner-low').forEach(b=>b.onclick=()=>ownerGiveLow(vs[b.dataset.i]));document.querySelectorAll('.owner-reactivate').forEach(b=>b.onclick=()=>ownerRequest(vs[b.dataset.i],'REACTIVACION_VEHICULO'));document.querySelectorAll('.owner-renew').forEach(b=>b.onclick=()=>ownerRequest(vs[b.dataset.i],'RENOVACION_QR'))}catch(e){err(e)}}
function ownerVehicle(v,i,h){const temporary=temporaryActive(v),pending=(state.cache.ownerRequests||[]).filter(r=>r.ID_Vehiculo===v.ID_Vehiculo&&r.Estado==='Pendiente');return `<article class="card"><div class="head"><h3>${v.Slot?`Vehículo ${esc(v.Slot)}`:'Vehículo sin slot'}</h3><span class="status ${v.Estado==='Activo'?'':'bad'}">${esc(v.Estado)}</span></div><div class="plate" style="font-size:2.2rem">${esc(temporary?v.MatriculaTemporal:v.MatriculaHabitual)}</div>${v.MatriculaTemporal?(temporary?`<div class="message">Temporal vigente hasta ${esc(dateEs(v.TemporalHasta))}</div>`:v.Estado!=='Activo'?`<div class="message bad">Matrícula temporal ${esc(v.MatriculaTemporal)} sin validez mientras el vehículo no esté activo.</div>`:''):''}<div class="details"><div><small>Vivienda</small>${esc(housingShort(h))}</div><div><small>Habitual</small>${esc(v.MatriculaHabitual)}</div><div><small>Marca/modelo</small>${esc(v.Marca)} ${esc(v.Modelo)}</div><div><small>Tipo</small>${esc(v.Tipo)}</div><div><small>Slot</small>${esc(v.Slot||'Liberado')}</div><div><small>Estado QR</small>${esc(v.QR_Estado||'—')}</div></div>${pending.length?`<div class="message">Solicitud pendiente: ${esc(pending.map(x=>requestTypeLabel(x.Tipo)).join(', '))}</div>`:''}<div class="actions" style="margin-top:1rem"><button class="owner-edit" data-i="${i}">Editar</button>${v.Estado==='Activo'&&v.QR_Estado==='Activo'?`<button class="secondary owner-qr" data-i="${i}">Ver / descargar QR</button>`:''}${v.Estado==='Activo'?`<button class="secondary owner-renew" data-i="${i}">Solicitar renovación QR</button><button class="danger owner-low" data-i="${i}">Dar de baja</button>`:`<button class="secondary owner-reactivate" data-i="${i}">Solicitar reactivación</button>`}</div></article>`}
async function ownerRequests(){try{const {hs,reqs}=await ownerData(),map=ownerHousingMap(hs);$('#main').innerHTML=`<div class="head"><h1>Mis solicitudes</h1></div><div class="filterbar"><div class="field filter-search"><label>Buscar</label><input id="owner-req-search" class="search" placeholder="Matrícula, vivienda, tipo o estado..."></div><div class="field"><label>Estado</label><select id="owner-req-state"><option value="Pendiente" selected>Pendientes</option><option value="">Todas</option><option>Aprobada</option><option>Rechazada</option></select></div><span class="count" id="owner-req-count"></span></div><div class="grid" id="owner-req-grid"></div>`;const render=()=>{const q=$('#owner-req-search').value.trim().toLowerCase(),st=$('#owner-req-state').value,filtered=reqs.filter(r=>(!st||r.Estado===st)&&Object.values(r).join(' ').toLowerCase().includes(q));$('#owner-req-count').textContent=`Mostrando ${filtered.length} de ${reqs.length}`;$('#owner-req-grid').innerHTML=filtered.map(r=>{const h=map[r.ID_Vivienda];return `<article class="card"><span class="status ${r.Estado==='Pendiente'?'bad':''}">${esc(r.Estado)}</span><h3>${esc(requestTypeLabel(r.Tipo))}</h3><div class="plate" style="font-size:1.7rem">${esc(r.MatriculaHabitual||'SIN MATRÍCULA')}</div><div class="details"><div><small>Vivienda</small>${esc(h?housingShort(h):`Bloque ${r.Bloque}, ${r.Planta} ${r.Apartamento}`)}</div><div><small>Fecha</small>${esc(r.FechaHora)}</div></div>${r.Motivo?`<p>${esc(r.Motivo)}</p>`:''}${r.Estado!=='Pendiente'?`<div class="message"><b>Resolución:</b> ${esc(r.Estado)}<br><b>Comentario:</b> ${esc(r.ObservacionesResolucion||'—')}<br><span class="subtle">${esc(r.Estado==='Aprobada'?'Aprobada':'Rechazada')} por ${esc(r.NombreResolucion||r.UsuarioResolucion||'—')} · ${esc(shortDateTime(r.FechaResolucion))}</span></div>`:''}</article>`}).join('')||'<div class="card empty">No tienes solicitudes.</div>'};$('#owner-req-search').oninput=render;$('#owner-req-state').onchange=render;render()}catch(e){err(e)}}
async function ownerQr(v){const available=v.Estado==='Activo'&&v.QR_Estado==='Activo';$('#main').innerHTML=`<div class="head"><h1>QR de mi vehículo</h1><button class="secondary" id="owner-qr-back">Volver</button></div><div class="grid"><div class="card result ${available?'':'bad'}"><span class="status ${available?'':'bad'}">${esc(v.QR_Estado)}</span><div class="plate" style="font-size:2.2rem">${esc(v.MatriculaHabitual)}</div><p>${esc(v.Marca)} ${esc(v.Modelo)}</p><div class="details"><div><small>Estado vehículo</small>${esc(v.Estado)}</div><div><small>Slot</small>${esc(v.Slot||'Liberado')}</div></div></div><div class="card" style="text-align:center"><h2>Código QR</h2>${available?`<div id="owner-qr-code" style="display:inline-block"></div><div class="actions" style="justify-content:center;margin-top:1rem"><button id="owner-qr-download">Descargar PNG</button><button class="secondary" id="owner-qr-print">Imprimir</button></div>`:`<div class="message bad">Este QR no está disponible.</div>`}</div></div>`;$('#owner-qr-back').onclick=ownerVehicles;if(!available)return;$('#owner-qr-print').onclick=()=>window.print();$('#owner-qr-download').disabled=true;try{await ensureQr();const size=qrSize();new QRCode($('#owner-qr-code'),{text:qrTarget(v.QR_Token),width:size,height:size,correctLevel:QRCode.CorrectLevel.L});$('#owner-qr-download').disabled=false}catch(e){$('#owner-qr-code').innerHTML=`<div class="message bad">${esc(e.message)}</div>`}$('#owner-qr-download').onclick=()=>{const box=$('#owner-qr-code'),canvas=box.querySelector('canvas'),img=box.querySelector('img'),url=canvas?canvas.toDataURL('image/png'):img?.src;if(!url){toast('No se pudo preparar el QR.',true);return}const a=document.createElement('a');a.href=url;a.download='QR_'+String(v.MatriculaHabitual||'vehiculo').replace(/[^A-Za-z0-9]/g,'')+'.png';document.body.appendChild(a);a.click();a.remove()}}
function ownerEditor(v){const host=$('#owner-editor'),tempBlocked=v.Estado!=='Activo';host.innerHTML=`<form class="card form" id="owner-form"><h2 class="wide">Editar vehículo</h2>${[['MatriculaHabitual','Matrícula habitual','text'],['MatriculaTemporal','Matrícula temporal','text'],['TemporalDesde','Desde','date'],['TemporalHasta','Hasta','date'],['Marca','Marca','text'],['Modelo','Modelo','text'],['Tipo','Tipo','select:Particular|Empresa|Alquiler|Otro']].map(f=>field(f,v)).join('')}<input type="hidden" name="Estado" value="${esc(v.Estado)}">${tempBlocked?'<div class="message wide">La matrícula temporal se conserva como histórico, pero no puede modificarse ni utilizarse mientras el vehículo no esté activo.</div>':''}<div class="wide actions"><button>Guardar</button><button type="button" class="secondary" id="owner-cancel">Cancelar</button></div></form>`;if(tempBlocked)['MatriculaTemporal','TemporalDesde','TemporalHasta'].forEach(n=>{const x=document.querySelector(`#owner-form [name="${n}"]`);if(x)x.readOnly=true});$('#owner-cancel').onclick=()=>host.innerHTML='';$('#owner-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));data.ID_Vehiculo=v.ID_Vehiculo;data.ModoPropietario='1';try{await call('saveVehicle',data);toast('Vehículo actualizado.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
function ownerAddVehicle(preselectedHousing=''){const host=$('#owner-editor')||$('#main'),hs=(state.cache.ownerHousing||[]).filter(h=>h.Estado==='Activa'),vs=state.cache.ownerVehicles||[];const availableHs=hs.filter(h=>vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda&&v.Estado==='Activo').length<2);if(!availableHs.length){toast('No hay slots libres en tus viviendas activas.',true);return}const selected=availableHs.some(h=>h.ID_Vivienda===preselectedHousing)?preselectedHousing:availableHs[0].ID_Vivienda,housingOptions=availableHs.map(h=>`<option value="${esc(h.ID_Vivienda)}" ${h.ID_Vivienda===selected?'selected':''}>${esc(housingShort(h))}</option>`).join('');host.innerHTML=`<form class="card form" id="owner-add-form"><h2 class="wide">Añadir vehículo</h2><div class="field wide"><label>Vivienda</label><select name="ID_Vivienda" id="owner-add-housing" required>${housingOptions}</select></div><div class="field"><label>Slot</label><select name="Slot" id="owner-add-slot" required></select></div>${[['MatriculaHabitual','Matrícula habitual','text'],['MatriculaTemporal','Matrícula temporal','text'],['TemporalDesde','Desde','date'],['TemporalHasta','Hasta','date'],['Marca','Marca','text'],['Modelo','Modelo','text'],['Tipo','Tipo','select:Particular|Empresa|Alquiler|Otro']].map(f=>field(f,{})).join('')}<div class="wide actions"><button>Crear vehículo</button><button type="button" class="secondary" id="owner-add-cancel">Cancelar</button></div></form>`;const refresh=()=>{const hid=$('#owner-add-housing').value,used=vs.filter(v=>v.ID_Vivienda===hid&&v.Estado==='Activo').map(v=>String(v.Slot)),free=['1','2'].filter(x=>!used.includes(x));$('#owner-add-slot').innerHTML=free.map(x=>`<option value="${x}">Slot ${x}</option>`).join('')||'<option value="">Sin slots disponibles</option>'};$('#owner-add-housing').onchange=refresh;refresh();$('#owner-add-cancel').onclick=()=>ownerVehicles();$('#owner-add-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));data.ModoPropietario='1';try{await call('saveVehicle',data);toast('Vehículo creado y QR generado.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
async function ownerGiveLow(v){if(!confirm(`¿Dar de baja ${v.MatriculaHabitual}? Se liberará el slot y el QR quedará revocado.`))return;try{await call('saveVehicle',{ID_Vehiculo:v.ID_Vehiculo,MatriculaHabitual:v.MatriculaHabitual,MatriculaTemporal:v.MatriculaTemporal,TemporalDesde:v.TemporalDesde,TemporalHasta:v.TemporalHasta,Marca:v.Marca,Modelo:v.Modelo,Tipo:v.Tipo,Estado:'Baja',ModoPropietario:'1'});toast('Vehículo dado de baja. Slot liberado y QR revocado.');await ownerData(true);ownerVehicles()}catch(e){err(e)}}
async function ownerRequest(v,type){const existing=(state.cache.ownerRequests||[]).some(r=>r.ID_Vehiculo===v.ID_Vehiculo&&r.Tipo===type&&r.Estado==='Pendiente');if(existing){toast('Ya existe una solicitud pendiente de este tipo.',true);return}const motivo=prompt(type==='REACTIVACION_VEHICULO'?'Motivo de la reactivación (opcional):':'Motivo de la renovación del QR (opcional):','');if(motivo===null)return;try{await call('createRequest',{ID_Vehiculo:v.ID_Vehiculo,Tipo:type,Motivo:motivo});toast('Solicitud registrada.');await ownerData(true);ownerVehicles()}catch(e){err(e)}}
function profile(){
  $('#main').innerHTML=`<form class="card form" id="profile-form"><h1 class="wide">Mis datos</h1><div class="field"><label>Email</label><input value="${esc(state.user.Email)}" disabled></div><div class="field"><label>Nombre</label><input name="Nombre" value="${esc(state.user.Nombre)}" required></div><div class="field"><label>Teléfono</label><input name="Telefono" value="${esc(state.user.Telefono)}"></div><div class="wide"><button>Guardar cambios</button></div></form><form class="card form" id="change-password-form" style="margin-top:1rem"><h2 class="wide">Cambiar contraseña</h2><div class="field"><label>Contraseña actual</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>Nueva contraseña</label><input name="newPassword" type="password" minlength="8" autocomplete="new-password" required></div><div class="wide"><span class="muted" style="font-size:.8rem">Mínimo 8 caracteres, con una letra y un número.</span></div><div class="wide"><button>Cambiar contraseña</button></div></form>`;
  $('#profile-form').onsubmit=async e=>{e.preventDefault();try{state.user=await call('updateProfile',Object.fromEntries(new FormData(e.target)));toast('Datos actualizados.');shell();go('profile')}catch(x){err(x)}};
  $('#change-password-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);try{await call('changePassword',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Contraseña actualizada.')}catch(x){toast(x.message,true)}finally{busy(b,false)}}
}
window.addEventListener('unhandledrejection',e=>{if(e&&e.reason)err(e.reason instanceof Error?e.reason:new Error(String(e.reason)))});
window.addEventListener('error',e=>{if(e&&e.error)err(e.error)});
init();
